// Port of Liverpool Grain Terminal — Information Portal
// Built by Dave (Senior Developer)
// Self-contained: all data embedded, no server required

// ── Data stores ───────────────────────────────────────────────────────────────
let allDrawings    = [];
let allEquipment   = [];
let equipAttrs     = {};
let equipRelations = [];
let activeFilter   = 'all';
let siteLayout     = null;
let activeLocation = null;
let activeSchematicLocation = null;
let feedbackCounter = 0;
const feedbackRegistry = {};
const FEEDBACK_STORAGE_KEY = 'pka-grain-terminal-feedback';
const LAYOUT_REGISTER_SOURCE = {
    label: 'Silo Layout Register',
    path: 'Equipment Register/Silo Layout PH CSV.csv',
    link: '../Grain Terminal/Equipment Register/Silo Layout PH CSV.csv',
};

// ── Helpers ───────────────────────────────────────────────────────────────────
function el(id) { return document.getElementById(id); }

function slugify(value) {
    return String(value || 'item')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .slice(0, 48) || 'item';
}

function escapeAttr(value) {
    return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

function findDocumentByDrawingRef(ref) {
    if (!ref) return null;
    return DATA_DOCUMENTS.find(d => d.drawing_ref === ref) || null;
}

function findDocumentByPathSuffix(pathSuffix) {
    if (!pathSuffix) return null;
    const needle = String(pathSuffix).toLowerCase();
    return DATA_DOCUMENTS.find(d => (d.file_path || '').toLowerCase().endsWith(needle)) || null;
}

function dedupeSources(sources) {
    const seen = new Set();
    return (sources || []).filter(source => {
        if (!source || !source.link) return false;
        const key = `${source.link}|${source.label || ''}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
    });
}

function buildSourceListHtml(sources, title = 'Source Files') {
    const deduped = dedupeSources(sources);
    if (deduped.length === 0) return '';
    return `<div class="detail-section source-section">
        <h4>${title}</h4>
        <div class="source-list-inline">
            ${deduped.map(source => `
                <a class="source-pill" href="${escapeAttr(source.link)}" target="_blank" rel="noopener" title="${escapeAttr(source.path || source.label)}">
                    ${source.label}
                </a>
            `).join('')}
        </div>
    </div>`;
}

function persistFeedbackRecord(record) {
    let existing = [];
    try {
        existing = JSON.parse(localStorage.getItem(FEEDBACK_STORAGE_KEY) || '[]');
        if (!Array.isArray(existing)) existing = [];
    } catch {
        existing = [];
    }
    existing.unshift(record);
    localStorage.setItem(FEEDBACK_STORAGE_KEY, JSON.stringify(existing));
    return existing;
}

function downloadJson(filename, payload) {
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    document.body.appendChild(anchor);
    anchor.click();
    document.body.removeChild(anchor);
    URL.revokeObjectURL(url);
}

function showToast(message) {
    let toast = document.getElementById('portal-toast');
    if (!toast) {
        toast = document.createElement('div');
        toast.id = 'portal-toast';
        toast.className = 'portal-toast';
        document.body.appendChild(toast);
    }
    toast.textContent = message;
    toast.classList.add('visible');
    clearTimeout(showToast.timer);
    showToast.timer = setTimeout(() => toast.classList.remove('visible'), 2400);
}

function registerFeedbackContext(context) {
    const id = `fb-${++feedbackCounter}`;
    feedbackRegistry[id] = context;
    return id;
}

function renderFeedbackPanel(context, compact = false) {
    const feedbackId = registerFeedbackContext(context);
    const klass = compact ? 'feedback-panel feedback-panel-compact' : 'feedback-panel';
    return `<div class="${klass}">
        <div class="feedback-copy">Was this correct?</div>
        <div class="feedback-actions">
            <button class="feedback-btn feedback-btn-ok" onclick="submitVerificationFeedback('${feedbackId}', 'correct')">Mark correct</button>
            <button class="feedback-btn feedback-btn-issue" onclick="submitVerificationFeedback('${feedbackId}', 'incorrect')">Report issue</button>
        </div>
    </div>`;
}

function createFeedbackRecord(context, verdict, comments) {
    const source = (context.sources && context.sources[0]) || {};
    return {
        item_type: context.item_type || 'document',
        item_id: context.item_id || '',
        item_label: context.item_label || 'Portal result',
        source_path: source.path || context.source_path || '',
        source_link: source.link || context.source_link || '',
        query_text: context.query_text || '',
        response_text: context.response_text || '',
        verdict,
        comments: comments || '',
        reported_by: 'portal-user',
        channel: context.channel || 'portal',
        status: 'open',
        created_at: new Date().toISOString(),
        sources: dedupeSources(context.sources || []),
    };
}

function submitVerificationFeedback(feedbackId, verdict) {
    const context = feedbackRegistry[feedbackId];
    if (!context) return;
    let comments = '';
    if (verdict === 'incorrect') {
        comments = window.prompt('What is wrong or missing? Include the correction if you know it.', '') || '';
        if (!comments.trim()) return;
    }
    const record = createFeedbackRecord(context, verdict, comments.trim());
    const allRecords = persistFeedbackRecord(record);
    if (verdict === 'incorrect') {
        const filename = `${slugify(record.item_label)}-issue-${record.created_at.replace(/[:.]/g, '-')}.json`;
        downloadJson(filename, record);
        showToast('Issue report saved as a JSON file for review.');
    } else {
        showToast('Marked as correct and added to the local verification log.');
    }
    window.__PKA_LAST_FEEDBACK_EXPORT = allRecords;
}

function gatherSourcesForEquipment(equip, drawings = null) {
    const refs = drawings || allDrawings.filter(d => (equip.drawing_refs || []).includes(d.drawing_ref));
    return dedupeSources(refs.map(d => ({
        label: d.drawing_ref || d.filename,
        path: d.file_path,
        link: d.pdf_link,
    })));
}

function gatherSourcesForAsset(asset, matchedEquipment = []) {
    const sources = [LAYOUT_REGISTER_SOURCE];
    asset.components.forEach(component => {
        const doc = findDocumentByPathSuffix(component.spec_source);
        if (doc) {
            sources.push({
                label: component.spec_source,
                path: doc.file_path,
                link: doc.pdf_link,
            });
        }
    });
    matchedEquipment.forEach(equip => {
        gatherSourcesForEquipment(equip).forEach(source => sources.push(source));
    });
    return dedupeSources(sources);
}

window.submitVerificationFeedback = submitVerificationFeedback;
window.PKASources = {
    buildSourceListHtml,
    gatherSourcesForEquipment,
    gatherSourcesForAsset,
    findDocumentByDrawingRef,
    layoutRegisterSource: LAYOUT_REGISTER_SOURCE,
};
window.PKAFeedback = {
    renderPanel: renderFeedbackPanel,
    createRecord: createFeedbackRecord,
};

// ── Initialisation ────────────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', function () {
    // Section navigation
    document.querySelectorAll('.nav-item').forEach(item => {
        item.addEventListener('click', function (e) {
            e.preventDefault();
            const targetId = this.getAttribute('href').substring(1);
            document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
            this.classList.add('active');
            document.querySelectorAll('.section').forEach(s => {
                s.classList.remove('active');
                if (s.id === targetId) s.classList.add('active');
            });
        });
    });

    el('detail-overlay').addEventListener('click', closeEquipmentDetail);

    loadStats();
    loadSchematics();
    loadPhotos();
    loadEquipment();
    loadSiteLayout();
    renderProcessSchematic();
    loadLubricants();
    loadPulleys();
    loadGearboxes();
    loadMotors();
    loadDustBags();
    loadDocuments();
});

// ── Stats ─────────────────────────────────────────────────────────────────────
function loadStats() {
    const stats = DATA_STATS;
    document.querySelectorAll('[data-stat]').forEach(elStat => {
        const key = elStat.dataset.stat;
        if (key === 'last_import') {
            elStat.textContent = stats.last_import ? stats.last_import.replace('T', ' ') : '—';
        } else if (stats[key] !== undefined) {
            elStat.textContent = stats[key];
        }
    });
}

// ── Schematics ────────────────────────────────────────────────────────────────
function loadSchematics() {
    allDrawings = DATA_DOCUMENTS.filter(d => d.category === 'electrical_drawing' || d.category === 'obsolete');
    renderMccFilters();
    renderDrawings();
    el('schematics-search').addEventListener('input', renderDrawings);
}

function renderMccFilters() {
    const mccs = [...new Set(allDrawings.map(d => d.mcc || 'Obsolete'))].sort((a, b) => {
        const numA = parseInt(a.replace('MCC', '')) || 999;
        const numB = parseInt(b.replace('MCC', '')) || 999;
        return numA - numB;
    });
    const bar = el('mcc-filter-bar');
    bar.innerHTML = '';
    const allPill = document.createElement('button');
    allPill.className = 'mcc-pill active';
    allPill.textContent = `All (${allDrawings.length})`;
    allPill.dataset.mcc = 'all';
    allPill.addEventListener('click', () => setMccFilter('all'));
    bar.appendChild(allPill);
    mccs.forEach(mcc => {
        const count = allDrawings.filter(d => (d.mcc || 'Obsolete') === mcc).length;
        const pill = document.createElement('button');
        pill.className = 'mcc-pill';
        pill.textContent = `${mcc} (${count})`;
        pill.dataset.mcc = mcc;
        pill.addEventListener('click', () => setMccFilter(mcc));
        bar.appendChild(pill);
    });
}

function setMccFilter(mcc) {
    activeFilter = mcc;
    document.querySelectorAll('.mcc-pill').forEach(p => {
        p.classList.toggle('active', p.dataset.mcc === mcc);
    });
    renderDrawings();
}

function renderDrawings() {
    const query = (el('schematics-search')?.value || '').toLowerCase().trim();
    let filtered = allDrawings;
    if (activeFilter !== 'all') filtered = filtered.filter(d => (d.mcc || 'Obsolete') === activeFilter);
    if (query) {
        filtered = filtered.filter(d =>
            (d.drawing_ref || '').toLowerCase().includes(query) ||
            (d.description || '').toLowerCase().includes(query) ||
            (d.filename    || '').toLowerCase().includes(query) ||
            (d.mcc         || '').toLowerCase().includes(query)
        );
    }
    const list  = el('schematics-list');
    const empty = el('schematics-empty');
    if (filtered.length === 0) { list.innerHTML = ''; empty.style.display = 'block'; return; }
    empty.style.display = 'none';
    list.innerHTML = filtered.map(d => {
        const linked = allEquipment.filter(e => (e.drawing_refs || []).includes(d.drawing_ref));
        const equipTags = linked.map(e =>
            `<span class="equip-tag" data-id="${e.id}" title="Open equipment detail">${e.name}</span>`
        ).join('');
        const sourceHtml = d.pdf_link
            ? `<a class="drawing-link" href="${d.pdf_link}" target="_blank" rel="noopener">Open source</a>`
            : `<span class="drawing-link dim">Source unavailable</span>`;
        const feedbackHtml = renderFeedbackPanel({
            item_type: 'drawing',
            item_id: String(d.id || d.drawing_ref || ''),
            item_label: d.drawing_ref || d.filename,
            source_path: d.file_path,
            source_link: d.pdf_link,
            response_text: d.description || d.filename,
            sources: d.pdf_link ? [{ label: d.drawing_ref || d.filename, path: d.file_path, link: d.pdf_link }] : [],
            channel: 'portal',
        }, true);
        return `<div class="drawing-row ${d.category === 'obsolete' ? 'drawing-obsolete' : ''}">
            <div class="drawing-ref">${d.drawing_ref || '—'}</div>
            <div class="drawing-desc">${d.description || d.filename}
                ${equipTags ? `<div class="drawing-equip-tags">${equipTags}</div>` : ''}
                ${feedbackHtml}
            </div>
            <div class="drawing-mcc">${d.mcc || 'Obsolete'}</div>
            ${sourceHtml}
        </div>`;
    }).join('');
    list.querySelectorAll('.equip-tag').forEach(tag => {
        tag.addEventListener('click', () => navigateToEquipment(parseInt(tag.dataset.id)));
    });
}

// ── Photos ────────────────────────────────────────────────────────────────────
function loadPhotos() {
    const photos = DATA_PHOTOS;
    const gallery = el('photo-gallery');
    const notice  = el('no-photos-notice');
    if (!photos || photos.length === 0) { notice.style.display = 'block'; return; }
    notice.style.display = 'none';
    photos.forEach(photo => {
        const card = document.createElement('div');
        card.className = `photo-card ${photo.approved ? 'approved' : 'unapproved'}`;
        card.innerHTML = `
            <div class="approval-status">${photo.approved ? 'APPROVED' : 'UNAPPROVED — AWAITING CONFIRMATION'}</div>
            <img src="${photo.url || photo.file_path || ''}" alt="${photo.caption}" onerror="this.style.display='none';">
            <div class="photo-info">
                <div class="photo-caption">${photo.caption}</div>
                ${photo.equipment_subject ? `<div class="photo-equip-subject">${photo.equipment_subject}</div>` : ''}
                ${photo.notes ? `<div class="photo-notes">${photo.notes}</div>` : ''}
                ${photo.url ? `<div class="drawing-actions"><a class="drawing-link" href="${photo.url}" target="_blank" rel="noopener">Open source</a></div>` : ''}
                ${renderFeedbackPanel({
                    item_type: 'photo',
                    item_id: String(photo.id || ''),
                    item_label: photo.caption,
                    source_path: photo.file_path,
                    source_link: photo.url,
                    response_text: `${photo.caption}${photo.notes ? ` — ${photo.notes}` : ''}`,
                    sources: photo.url ? [{ label: photo.caption, path: photo.file_path, link: photo.url }] : [],
                    channel: 'portal',
                }, true)}
            </div>`;
        gallery.appendChild(card);
    });
}

// ── Lubricants ────────────────────────────────────────────────────────────────
function loadLubricants() {
    const input = el('lubricants-search');
    if (!input) return;
    input.addEventListener('input', renderLubricants);
    renderLubricants();
}

function renderLubricants() {
    const list = el('lubricants-list');
    const empty = el('lubricants-empty');
    if (!list || !empty) return;
    const query = (el('lubricants-search')?.value || '').toLowerCase().trim();
    const rows = (DATA_LUBRICANTS || []).filter(item => {
        if (!query) return true;
        return [
            item.supplier,
            item.product_description,
            item.ordering_instructions,
            item.used_for,
        ].some(value => String(value || '').toLowerCase().includes(query));
    });
    empty.style.display = rows.length ? 'none' : 'block';
    list.innerHTML = rows.map(item => {
        const assignments = (DATA_EQUIPMENT_LUBRICANTS || []).filter(link => link.lubricant_id === item.id);
        const linkedCount = assignments.filter(link => link.equipment_id).length;
        const unlinkedCount = assignments.length - linkedCount;
        const assignmentPreview = assignments.slice(0, 10).map(link => link.equipment_id
            ? `<span class="equip-tag" onclick="navigateToEquipment(${link.equipment_id})">${link.equipment_name}</span>`
            : `<span class="lubricant-unlinked">${link.source_equipment_label}</span>`
        ).join('');
        const moreCount = assignments.length > 10 ? `<span class="lubricant-more">+${assignments.length - 10} more</span>` : '';
        return `
        <div class="lubricant-card">
            <div class="lubricant-main">
                <div class="lubricant-product">${item.product_description}</div>
                <div class="lubricant-meta">
                    <span>${item.supplier || '—'}</span>
                    <span>${item.ordering_instructions || 'No ordering note'}</span>
                    <span>${linkedCount} linked${unlinkedCount ? ` · ${unlinkedCount} pending` : ''}</span>
                </div>
            </div>
            <div class="lubricant-used-for">${item.used_for || 'Use not recorded'}</div>
            ${assignments.length ? `<div class="lubricant-assignment-list">${assignmentPreview}${moreCount}</div>` : ''}
            <div class="lubricant-source">Source: ${item.source_file || 'Lubricant register CSV'}</div>
        </div>
    `;
    }).join('');
}

